import{_ as r,C as o,o as e,c as l,a2 as t,b as s,w as n,a as h,E as g,a3 as p}from"./chunks/framework.DToEn73J.js";const b=JSON.parse('{"title":"部署与弹性伸缩","description":"","frontmatter":{"title":"部署与弹性伸缩","chapter":"6.5","order":5,"summary":"多 Agent 实例隔离、多租户资源隔离与基于 CI/CD 的灰度发布工程实践。"},"headers":[],"relativePath":"06-engineering-ops/deployment-scaling.md","filePath":"06-engineering-ops/deployment-scaling.md","lastUpdated":1788255095000}'),d={name:"06-engineering-ops/deployment-scaling.md"};function c(A,a,E,u,m,_){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="部署与弹性伸缩" tabindex="-1">部署与弹性伸缩 <a class="header-anchor" href="#部署与弹性伸缩" aria-label="Permalink to &quot;部署与弹性伸缩&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>Agent 是有状态、长程、会调外部 Tool 的服务。本页解决“如何在不共享危险状态、不被单租户拖垮、且可安全回滚的前提下横向扩展 Agent 实例”。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ul><li><strong>并发模型（实例隔离）</strong>：每个会话/任务跑独立 Agent 实例，状态留在 Checkpoint 而非进程内存；用 Orchestrator-Worker 派发子任务，Worker 间通过消息而非共享变量通信（见 2.4）。</li><li><strong>多租户资源隔离</strong>：用命名空间 + 配额（并发数、token 预算、Tool 调用额度）隔离租户；危险 Tool 走 Permission Sandbox 单独鉴权（见 2.3）。</li><li><strong>CI/CD 与灰度</strong>：模型/Prompt/代码变更经评估门禁（见 6.3）后，先 canary 小流量，按错误率与成本护栏（Guardrails）自动放量或回滚。</li></ul>',5)),(e(),s(p,null,{default:n(()=>[g(i,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E6%8F%90%E4%BA%A4%E5%8F%98%E6%9B%B4%5D%20--%3E%20B%5BCI%3A%20%E8%AF%84%E4%BC%B0%E9%97%A8%E7%A6%81%5D%0A%20%20%20%20B%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20C%5BCanary%205%25%5D%0A%20%20%20%20C%20--%3E%20D%7B%E6%8A%A4%E6%A0%8F%20OK%3F%7D%0A%20%20%20%20D%20--%3E%7C%E6%98%AF%7C%20E%5B%E9%80%90%E6%AD%A5%E6%94%BE%E9%87%8F%5D%0A%20%20%20%20D%20--%3E%7C%E5%90%A6%7C%20F%5B%E8%87%AA%E5%8A%A8%E5%9B%9E%E6%BB%9A%5D%0A%20%20%20%20E%20--%3E%20G%5B%E5%85%A8%E9%87%8F%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h2><p>Agent 实例若共享内存状态，一个租户的 Checkpoint 污染会串到他人；无配额则单租户的失控 Agent Loop 占满 token 预算拖垮全局。隔离 + 灰度把“一次坏变更”的爆炸半径限制在单实例/小流量内。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>把长程 Agent 跑成常驻进程却不落 Checkpoint，崩溃即丢失全部进度。</li><li>灰度只看 QPS，忽略成本漂移——新模型可能更贵却更慢。</li></ul><h2 id="业界实现对照" tabindex="-1">业界实现对照 <a class="header-anchor" href="#业界实现对照" aria-label="Permalink to &quot;业界实现对照&quot;">​</a></h2><ul><li><strong>LangGraph Platform</strong>（带状态的服务化部署，<a href="https://langchain-ai.github.io/langgraph/%EF%BC%89%E3%80%82" target="_blank" rel="noreferrer">https://langchain-ai.github.io/langgraph/）。</a></li><li><strong>OpenAI Agents SDK deployment</strong>（<a href="https://openai.github.io/openai-agents-python/%EF%BC%89%E3%80%82" target="_blank" rel="noreferrer">https://openai.github.io/openai-agents-python/）。</a></li><li><strong>Kubernetes + KEDA</strong> 基于队列深度的弹性伸缩。</li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/fk-ai-agent/02-capability-extension/permission-sandbox">/02-capability-extension/permission-sandbox</a></li><li><a href="/fk-ai-agent/02-capability-extension/multi-agent">/02-capability-extension/multi-agent</a></li><li><a href="/fk-ai-agent/06-engineering-ops/evaluation-swebench">/06-engineering-ops/evaluation-swebench</a></li><li><a href="/fk-ai-agent/05-safety-governance/kill-switch">/05-safety-governance/kill-switch</a></li></ul><hr><p><em>最后核实日期：2026-08-26</em></p>',10))])}const C=r(d,[["render",c]]);export{b as __pageData,C as default};
